  commit.onclick=async()=>{if(!base64)return;commit.disabled=true;try{const r=await api('/admin/import-schedule',{base64});m.close();classes=await api('/classes');await masters();toast(r.count+' jadwal berhasil diimport. Gunakan Sinkron peserta untuk mengisi daftar mahasiswa.')}catch(e){toast(e.message);commit.disabled=false}};
