function createUser(){
  const available=masterData.mahasiswa.filter(m=>!masterData.users.some(u=>u.mahasiswa_id===m.id));
  const m=dialog(`<form><h2>Tambah akun pengguna</h2><label>Role<select name="role">${Object.entries(roleLabel).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label id="student-link" hidden>Mahasiswa / NIM<select name="mahasiswa_id"><option value="">Pilih mahasiswa…</option>${available.map(s=>`<option value="${s.id}">${esc(s.nim)} · ${esc(s.name)}</option>`).join('')}</select><small>Satu mahasiswa hanya dapat dihubungkan ke satu akun.</small></label><label>Nama<input name="name" required></label><label>Email login<input name="email" type="email" required autocomplete="off"></label><label>Password awal (minimal 12 karakter)<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><div class="row"><button type="button" data-close>Batal</button><button class="primary">Buat akun</button></div></form>`);
  const form=m.querySelector('form'),role=form.elements.role,student=form.elements.mahasiswa_id,name=form.elements.name;
  const sync=()=>{const linked=role.value==='mahasiswa';m.querySelector('#student-link').hidden=!linked;student.required=linked;name.readOnly=linked;if(linked)name.value=available.find(s=>s.id===Number(student.value))?.name||'';};
  role.onchange=sync;student.onchange=sync;sync();
  form.onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));if(values.role==='mahasiswa')values.mahasiswa_id=Number(values.mahasiswa_id);else delete values.mahasiswa_id;try{await api('/admin/users',values);m.close();await masters();toast('Akun pengguna berhasil dibuat.')}catch(x){toast(x.message)}};
}
